    }
  ],
  "evidence": [
    {
      "id": "SRC-WAVE-BRIEF",
      "quote": "The authors discuss spatial coarsening; infer additional hypotheses rather than claiming this published finding as new.",
      "locator": "wave 情境材料 additional_context",
      "note": "明确区分已发表方向与可提出的后续假说。"
    },
    {
      "id": "SRC-WAVE-BRIEF",
      "quote": "This subset contains 2199 time samples from an exported experimental aggregate, not 2199 independent runs; underlying image sequences and repeated-run identifiers are not included.",
